<template><section><div class="mb-6 flex justify-between"><div><h1 class="text-2xl font-bold">{{t('subscriptions.title')}}</h1></div><button class="btn-primary" @click="modal=true">+ {{t('subscriptions.new')}}</button></div><div class="card overflow-x-auto"><table class="w-full text-sm"><thead class="text-xs text-slate-500"><tr><th class="p-3 text-start">{{t('subscriptions.user')}}</th><th class="p-3 text-start">{{t('subscriptions.format')}}</th><th class="p-3 text-start">{{t('common.status')}}</th><th class="p-3 text-start">{{t('subscriptions.url')}}</th><th class="p-3 text-end">{{t('common.actions')}}</th></tr></thead><tbody><tr v-for="s in rows" :key="s.id" class="border-t border-white/5"><td class="p-3">{{s.email||s.user_id}}</td><td class="p-3">{{s.format}}</td><td class="p-3">{{s.disabled?t('common.disabled'):t('common.enabled')}}</td><td class="max-w-xs truncate p-3 font-mono text-xs text-slate-500">{{url(s.token)}}</td><td class="p-3 text-end"><button class="btn-ghost me-1" @click="copy(url(s.token))">{{t('common.copy')}}</button><button class="btn-ghost me-1" @click="regen(s.id)">{{t('subscriptions.regenerate')}}</button><button class="btn-ghost me-1" @click="toggle(s)">{{s.disabled?t('subscriptions.enable'):t('subscriptions.disable')}}</button><button class="btn-danger" @click="remove(s.id)">{{t('common.delete')}}</button></td></tr></tbody></table><div v-if="!rows.length" class="p-10 text-center text-slate-600">{{t('common.noData')}}</div></div><div v-if="modal" class="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4"><form class="card w-full max-w-md" @submit.prevent="create"><h2 class="mb-4 text-lg font-semibold">{{t('subscriptions.new')}}</h2><select v-model.number="form.userId" class="input mb-3" required><option :value="0" disabled>{{t('subscriptions.user')}}</option><option v-for="u in users" :value="u.id" :key="u.id">{{u.email||u.uuid}}</option></select><select v-model="form.format" class="input"><option v-for="f in formats" :key="f" :value="f">{{f}}</option></select><div class="mt-5 flex justify-end gap-2"><button type="button" class="btn-ghost" @click="modal=false">{{t('common.cancel')}}</button><button class="btn-primary">{{t('common.create')}}</button></div></form></div></section></template>
<script setup lang="ts">import{ref}from'vue';import{useI18n}from'vue-i18n';import{api}from'../api/client';const{t}=useI18n(),rows=ref<any[]>([]),users=ref<any[]>([]),modal=ref(false),formats=['plain','base64','clash-meta','sing-box','v2rayn','nekobox'],form=ref({userId:0,format:'plain'});const url=(token:string)=>`${location.origin}/api/configs/sub/${token}`;async function load(){rows.value=(await api.get<any>('/subscriptions')).subscriptions||[];users.value=(await api.get<any>('/users?pageSize=100')).users||[]}async function create(){await api.post('/subscriptions',form.value);modal.value=false;form.value={userId:0,format:'plain'};await load()}async function regen(id:number){await api.post(`/subscriptions/${id}/regenerate`);await load()}async function toggle(s:any){await api.patch(`/subscriptions/${s.id}`,{disabled:!s.disabled});await load()}async function remove(id:number){if(confirm('Delete subscription?')){await api.delete(`/subscriptions/${id}`);await load()}}async function copy(x:string){try{await navigator.clipboard?.writeText(x)}catch{prompt('Copy the subscription URL:',x)}}load();</script>
